mapper.select:
/* Attd02Mapper.selectHoliday */ SELECT A.CMPNY_CD AS cmpnyCd , A.HOLIDAY_ID AS holidayId , A.HOLIDAY_NM AS holidayNm , A.HOLIDAY_YMD AS holidayYmd , A.HOLIDAY_TYPE AS holidayType , A.USE_YN AS useYn , A.INSERT_NO AS insertNo , NULLIF(FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'USER_NM' , A.INSERT_NO , null ), '') AS insertNm , DATE_FORMAT(INSERT_DATE, '%Y%m%d') AS insertDate FROM TB_HOLIDAY A WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd} AND A.USE_YN = 'Y' AND HOLIDAY_YMD >= STR_TO_DATE(CONCAT(#{year}, LPAD(#{month}, 2, '0'), '01'), '%Y%m%d') AND HOLIDAY_YMD < DATE_ADD(STR_TO_DATE(CONCAT(#{year}, LPAD(#{month}, 2, '0'), '01'), '%Y%m%d'), INTERVAL 1 MONTH)
UNION ALL
SELECT A.CMPNY_CD AS cmpnyCd , A.HOLIDAY_RULE_ID AS holidayId , A.HOLIDAY_RULE_NM AS holidayNm , CONCAT( #{year} , '-' , A.HOLIDAY_MM , '-' , A.HOLIDAY_DD ) AS holidayYmd , A.HOLIDAY_TYPE AS holidayType , A.USE_YN AS useYn , A.INSERT_NO AS insertNo , NULLIF(FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'USER_NM' , A.INSERT_NO , null ), '') AS insertNm , DATE_FORMAT(INSERT_DATE, '%Y%m%d') AS insertDate FROM TB_HOLIDAY_RULE A WHERE 1=1 AND A.CMPNY_CD = #{gvCmpnyCd} AND A.USE_YN = 'Y' AND A.HOLIDAY_MM = LPAD(#{month}, 2, '0')
